/* Customer AMC information is descriptive; it does not automatically change billing. */
if(!db.lists['AMC Types'])db.lists['AMC Types']=['Basic AMC','Comprehensive AMC'];
schemas.customers.push(section('AMC / ANNUAL MAINTENANCE CONTRACT'),{key:'amcType',label:'AMC Type',type:'select',options:()=>db.lists['AMC Types']||[]},{key:'amcStart',label:'AMC Valid From',type:'date'},{key:'amcExpiry',label:'AMC Valid Until',type:'date'},{key:'amcRef',label:'AMC Agreement / Reference No.'},{key:'amcNotes',label:'AMC Coverage / Notes',type:'textarea',full:true});
function validAmcDate(value){return typeof value==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(value)&&!Number.isNaN(new Date(value+'T00:00:00Z').getTime())&&new Date(value+'T00:00:00Z').toISOString().slice(0,10)===value}
function validateCustomerAmc(c){if(!c.amcType){if(c.amcStart||c.amcExpiry)throw Error('Select an AMC type, or clear its validity dates.');return true}if(!validAmcDate(c.amcStart)||!validAmcDate(c.amcExpiry))throw Error('Enter both AMC validity dates.');if(c.amcExpiry<c.amcStart)throw Error('AMC validity end date must be on or after its start date.');return true}
function customerAmcStatus(c,date=today()){if(!c.amcType)return 'No AMC';if(!validAmcDate(c.amcStart)||!validAmcDate(c.amcExpiry)||c.amcExpiry<c.amcStart)return 'Incomplete';if(c.amcStart>date)return 'Not Started';if(c.amcExpiry<date)return 'Expired';return 'Active'}
const editBeforeCustomerAmc=editRecord;
editRecord=function(key,id,initial){editBeforeCustomerAmc(key,id,initial);if(key!=='customers')return;let form=$('#recordForm');if(!form)return;let type=form.querySelector('[name="amcType"]'),current=id?find('customers',id):initial;if(type&&current?.amcType&&!Array.from(type.options).some(o=>o.value===current.amcType)){let option=document.createElement('option');option.value=option.textContent=current.amcType;type.appendChild(option);type.value=current.amcType}let submit=form.onsubmit;form.onsubmit=e=>{let values=Object.fromEntries(new FormData(form));try{validateCustomerAmc(values)}catch(err){e.preventDefault();return toast(err.message)}return submit(e)}};
let customerAmcFilter='';
const basicBeforeCustomerAmc=basicPage;
basicPage=function(key){if(key!=='customers')return basicBeforeCustomerAmc(key);let rows=db.customers.filter(c=>matches({...c,amcStatus:customerAmcStatus(c)})).filter(c=>!customerAmcFilter||customerAmcStatus(c)===customerAmcFilter);return toolbar('Add Customer',`<select id="customerAmcFilter" aria-label="Filter customers by AMC"><option value="">All AMC Statuses</option>${opts(['Active','Expired','Not Started','No AMC','Incomplete'],customerAmcFilter)}</select>`)+table(['Customer ID','Customer Name','Mobile Number','Alt Mobile','Email ID','Address','City','State','PIN','GST Number','Type','DOB','AMC Type','AMC Valid From','AMC Valid Until','AMC Status','AMC Reference','AMC Notes','Actions'],rows.map(c=>[esc(c.id),`<strong>${esc(c.name)}</strong>`,esc(c.mobile),esc(c.alt||'—'),esc(c.email||'—'),esc(c.address||'—'),esc(c.city||'—'),esc(c.state||'—'),esc(c.pin||'—'),esc(c.gst||'—'),badge(c.type),esc(c.dob||'—'),esc(c.amcType||'—'),esc(c.amcStart||'—'),esc(c.amcExpiry||'—'),badge(customerAmcStatus(c)),esc(c.amcRef||'—'),esc(c.amcNotes||'—'),actions(key,c.id)]))};
const renderBeforeCustomerAmc=render;
render=function(){renderBeforeCustomerAmc();if(page==='customers'&&$('#customerAmcFilter'))$('#customerAmcFilter').onchange=e=>{customerAmcFilter=e.target.value;render()}};
render();
